198	    private Evaluator parsePseudoSelector() {
199	        final String pseudo = tq.consumeCssIdentifier();
200	        switch (pseudo) {
201	            case "lt":
202	                return new Evaluator.IndexLessThan(consumeIndex());
203	            case "gt":
204	                return new Evaluator.IndexGreaterThan(consumeIndex());
205	            case "eq":
206	                return new Evaluator.IndexEquals(consumeIndex());
207	            case "has":
208	                return has();
209	            case "is":
210	                return is();
211	            case "contains":
212	                return contains(false);
213	            case "containsOwn":
214	                return contains(true);
215	            case "containsWholeText":
216	                return containsWholeText(false);
217	            case "containsWholeOwnText":
218	                return containsWholeText(true);
219	            case "containsData":
220	                return containsData();
221	            case "matches":
222	                return matches(false);
223	            case "matchesOwn":
224	                return matches(true);
225	            case "matchesWholeText":
226	                return matchesWholeText(false);
227	            case "matchesWholeOwnText":
228	                return matchesWholeText(true);
229	            case "not":
230	                return not();
231	            case "lang":
232	                return lang();
233	            case "nth-child":
234	                return cssNthChild(false, false);
235	            case "nth-last-child":
236	                return cssNthChild(true, false);
237	            case "nth-of-type":
238	                return cssNthChild(false, true);
239	            case "nth-last-of-type":
240	                return cssNthChild(true, true);
241	            case "first-child":
242	                return new Evaluator.IsFirstChild();
243	            case "last-child":
244	                return new Evaluator.IsLastChild();
245	            case "first-of-type":
246	                return new Evaluator.IsFirstOfType();
247	            case "last-of-type":
248	                return new Evaluator.IsLastOfType();
249	            case "only-child":
250	                return new Evaluator.IsOnlyChild();
251	            case "only-of-type":
252	                return new Evaluator.IsOnlyOfType();
253	            case "empty":
254	                return new Evaluator.IsEmpty();
255	            case "blank":
256	                return new NodeEvaluator.BlankValue();
257	            case "root":
258	                return new Evaluator.IsRoot();
259	            case "scope":
260	                return new StructuralEvaluator.Scope();
261	            case "matchText": {
262	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
263	                Evaluator.MatchText matchText = new Evaluator.MatchText();
264	                return matchText;
265	            }
266	            default:
267	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
268	        }
269	    }
270	
271	    // ::comment etc
272	    private Evaluator parseNodeSelector() {
273	        final String pseudo = tq.consumeCssIdentifier();
274	        inNodeContext = true;  // Enter node context
275	
276	        Evaluator left;
277	        switch (pseudo) {
278	            case "node":
279	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
280	                break;
281	            case "leafnode":
282	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
283	                break;
284	            case "text":
285	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
286	                break;
287	            case "comment":
288	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
289	                break;
290	            case "data":
291	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
292	                break;
293	            case "cdata":
294	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
295	                break;
296	            default:
297	                throw new Selector.SelectorParseException(
298	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
299	        }
300	
301	        // Handle following subclasses in node context (like ::comment:contains())
302	        Evaluator right;
303	        while ((right = parseSubclass()) != null) {
304	            left = and(left, right);
305	        }
306	
307	        inNodeContext = false;
308	        return left;
309	    }
310	
311	    private Evaluator byId() {
312	        String id = tq.consumeCssIdentifier();
313	        Validate.notEmpty(id);
314	        return new Evaluator.Id(id);
315	    }
316	
317	    private Evaluator byClass() {
318	        String className = tq.consumeCssIdentifier();
319	        Validate.notEmpty(className);
320	        return new Evaluator.Class(className.trim());
321	    }
322	
323	    private Evaluator byTag() {
324	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
325	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
326	        // consistency - both the selector and the element tag
327	        String tagName = normalize(tq.consumeElementSelector());
328	        Validate.notEmpty(tagName);
329	
330	        // namespaces:
331	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
332	            String plainTag = tagName.substring(2); // strip *|
333	            return new CombiningEvaluator.Or(
334	                new Evaluator.Tag(plainTag),
335	                new Evaluator.TagEndsWith(":" + plainTag)
336	            );
337	        } else if (tagName.endsWith("|*")) { // ns|*
338	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
339	            return new Evaluator.TagStartsWith(ns);
340	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
341	            tagName = tagName.replace("|", ":");
342	        }
343	
344	        return new Evaluator.Tag(tagName);
345	    }
346	
347	    private Evaluator byAttribute() {
348	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
349	            return evaluatorForAttribute(cq);
350	        }
351	    }
352	
353	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
354	        cq.consumeWhitespace();
355	        String key = consumeAttributeKey(cq);
356	        key = normalize(key);
357	        Validate.notEmpty(key);
358	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
359	        cq.consumeWhitespace();
360	        final Evaluator eval;
361	
362	        if (cq.isEmpty()) {
363	            if (key.startsWith("^"))
364	                eval = new Evaluator.AttributeStarting(key.substring(1));
365	            else if (key.equals("*")) // any attribute
366	                eval = new Evaluator.AttributeStarting("");
367	            else
368	                eval = new Evaluator.Attribute(key);
369	        } else if (cq.matchChomp("~=")) { // regex match; the remainder of the queue (less surrounding whitespace) is the pattern
370	            eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder().trim()));
371	        } else {
372	            final String op;
373	            if (cq.matchChomp("!=")) op = "!=";
374	            else if (cq.matchChomp("^=")) op = "^=";
375	            else if (cq.matchChomp("$=")) op = "$=";
376	            else if (cq.matchChomp("*=")) op = "*=";
377	            else if (cq.matchChomp("=")) op = "=";
378	            else throw new Selector.SelectorParseException(
379	                "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
380	
381	            cq.consumeWhitespace();
382	            final String rawValue = consumeAttributeValue(cq);
383	            final boolean quoted = !rawValue.isEmpty() && (rawValue.charAt(0) == '"' || rawValue.charAt(0) == '\'');
384	            // Quoted (CSS string) values keep their quotes and are decoded in the evaluator; bare values have their
385	            // CSS escapes decoded here, so escaped and unescaped forms of the same value match equally.
386	            final String value = quoted ? rawValue : TokenQueue.unescapeCss(rawValue);
387	            cq.consumeWhitespace();
388	
389	            // Quoted (CSS string) values compare case-sensitively by default; bare values keep jsoup's historical
390	            // case-insensitive compare. An 'i' or 's' modifier after the value overrides the default.
391	            boolean caseSensitive = quoted;
392	            if (!cq.isEmpty()) {
393	                String modifier = cq.consumeCssIdentifier();
394	                if (modifier.equalsIgnoreCase("s")) caseSensitive = true;
395	                else if (modifier.equalsIgnoreCase("i")) caseSensitive = false;
396	                else throw new Selector.SelectorParseException(
397	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, modifier + cq.remainder());
398	                cq.consumeWhitespace();
399	                if (!cq.isEmpty())
400	                    throw new Selector.SelectorParseException(
401	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
402	            }
403	
404	            switch (op) {
405	                case "=":
406	                    eval = new Evaluator.AttributeWithValue(key, value, caseSensitive);
407	                    break;
408	                case "!=":
409	                    eval = new Evaluator.AttributeWithValueNot(key, value, caseSensitive);
410	                    break;
411	                case "^=":
412	                    eval = new Evaluator.AttributeWithValueStarting(key, value, caseSensitive);
413	                    break;
414	                case "$=":
415	                    eval = new Evaluator.AttributeWithValueEnding(key, value, caseSensitive);
416	                    break;
417	                case "*=":
418	                    eval = new Evaluator.AttributeWithValueContaining(key, value, caseSensitive);
419	                    break;
420	                default:
421	                    throw new Selector.SelectorParseException(
422	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
423	            }
424	        }
425	        return eval;
426	    }
427	
428	    /**
429	     Consumes an attribute key off the queue, up to (but not including) whitespace or a comparison operator. CSS
430	     escapes in the key are decoded.
431	     */
432	    private String consumeAttributeKey(TokenQueue cq) {
433	        StringBuilder sb = StringUtil.borrowBuilder();
434	        OUT: while (!cq.isEmpty()) {
435	            if (cq.matchesWhitespace()) break;
436	            for (String eval : AttributeEvals) {
437	                if (cq.matches(eval)) break OUT;
438	            }
439	            if (cq.matches('\\')) cq.consumeCssEscapeSequence(sb);
440	            else sb.append(cq.consume());
441	        }
442	        return StringUtil.releaseBuilder(sb);
443	    }
444	
445	    /**
446	     Consumes an attribute value off the queue: either a quoted string (returned with its quotes, for decoding in the
447	     evaluator), or a bare value running to the next whitespace or the end of the queue.
448	     */
449	    private String consumeAttributeValue(TokenQueue cq) {
450	        if (cq.isEmpty()) return "";
451	
452	        if (cq.matches('"') || cq.matches('\'')) {
453	            StringBuilder sb = StringUtil.borrowBuilder();
454	            char quote = cq.consume();
455	            sb.append(quote);
456	            boolean closed = false;
457	            while (!cq.isEmpty()) {
458	                char c = cq.consume();
459	                sb.append(c);
460	                if (c == '\\' && !cq.isEmpty()) {
461	                    sb.append(cq.consume()); // keep the escaped character with its escape, for balanced decoding
462	                } else if (c == quote) {
463	                    closed = true;
464	                    break;
465	                }
466	            }
467	            if (!closed) {
468	                StringUtil.releaseBuilderVoid(sb);
469	                throw new Selector.SelectorParseException("Quoted value must have content");
470	            }
471	            return StringUtil.releaseBuilder(sb);
472	        }
473	
474	        // bare value, up to the next whitespace or the end of the queue
475	        StringBuilder sb = StringUtil.borrowBuilder();
476	        while (!cq.isEmpty() && !cq.matchesWhitespace()) sb.append(cq.consume());
477	        return StringUtil.releaseBuilder(sb);
478	    }
479	
480	    //pseudo selectors :first-child, :last-child, :nth-child, ...
481	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
482	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
483	
484	    private Evaluator cssNthChild(boolean last, boolean ofType) {
485	        String raw = consumeParens(); // arg is like "odd", or "-n+2", within nth-child(odd), optionally followed by " of S"
486	        final int ofIdx = indexOfOfClause(raw);
487	        final String arg = normalize(ofIdx >= 0 ? raw.substring(0, ofIdx) : raw);
488	        final boolean hasOf = ofIdx >= 0;
489	
490	        if (hasOf && ofType)
491	            throw new Selector.SelectorParseException(
492	                "Could not parse query '%s': 'of S' is only supported by :nth-child and :nth-last-child", query);
493	
494	        final int step, offset;
495	        if ("odd".equals(arg)) {
496	            step = 2;
497	            offset = 1;
498	        } else if ("even".equals(arg)) {
499	            step = 2;
500	            offset = 0;
501	        } else {
502	            Matcher stepOffsetM, stepM;
503	            if ((stepOffsetM = NthStepOffset.matcher(arg)).matches()) {
504	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
505	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
506	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
507	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
508	                offset =
509	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
510	            } else if ((stepM = NthOffset.matcher(arg)).matches()) {
511	                step = 0;
512	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
513	            } else {
514	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", arg);
515	            }
516	        }
517	
518	        if (hasOf) {
519	            String subQuery = raw.substring(ofIdx + 2).trim(); // skip the "of" keyword
520	            Validate.notEmpty(subQuery, ":nth-child(An+B of S) selector S must not be empty");
521	            Evaluator selector = parse(subQuery); // a comma-separated complex selector list; validates the full grammar
522	            return new Evaluator.IsNthChildOf(step, offset, last, selector);
523	        }
524	
525	        return ofType
526	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
527	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
528	    }
529	
530	    /**
531	     Finds the index of the {@code of} keyword separating An+B from the selector list in an
532	     {@code :nth-child(An+B of S)} argument. The keyword must be bounded on both sides by whitespace, and is not
533	     matched inside quoted strings (so attribute values containing " of " are preserved).
534	     @return the index of the 'o' in 'of', or -1 if there is no of clause
535	     */
536	    private static int indexOfOfClause(String arg) {
537	        boolean inSingle = false;
538	        boolean inDouble = false;
539	        boolean prevEscaped = false;
540	        for (int i = 0; i < arg.length(); i++) {
541	            char c = arg.charAt(i);
542	            if (c == '\\' && i + 1 < arg.length()) {
543	                i++; // skip the escaped char
544	                prevEscaped = true;
545	                continue;
546	            }
547	            if (!inDouble && c == '\'')
548	                inSingle = !inSingle;
549	            else if (!inSingle && c == '"')
550	                inDouble = !inDouble;
551	
552	            if (!inSingle && !inDouble && !prevEscaped
553	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
554	                && arg.regionMatches(true, i, "of", 0, 2)
555	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
556	                return i;
557	            }
558	            prevEscaped = false;
559	        }
560	        return -1;
561	    }
562	
563	    private String consumeParens() {
564	        return tq.chompBalanced('(', ')');
565	    }
566	
567	    private int consumeIndex() {
568	        String index = consumeParens().trim();
569	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
570	        return Integer.parseInt(index);
571	    }
572	
573	    // pseudo selector :has(el)
574	    private Evaluator has() {
575	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
576	    }
577	
578	    // pseudo selector :is()
579	    private Evaluator is() {
580	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
581	    }
582	
583	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
584	        Validate.isTrue(tq.matchChomp('('), err);
585	        Evaluator eval = parseSelectorGroup();
586	        Validate.isTrue(tq.matchChomp(')'), err);
587	        return func.apply(eval);
588	    }
589	
590	    // pseudo selector :contains(text), containsOwn(text)
591	    private Evaluator contains(boolean own) {
592	        String query = own ? ":containsOwn" : ":contains";
593	        String searchText = TokenQueue.unescape(consumeParens());
594	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
595	
596	        if (inNodeContext)
597	            return new NodeEvaluator.ContainsValue(searchText);
598	
599	        return own
600	            ? new Evaluator.ContainsOwnText(searchText)
601	            : new Evaluator.ContainsText(searchText);
602	    }
603	
604	    private Evaluator containsWholeText(boolean own) {
605	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
606	        String searchText = TokenQueue.unescape(consumeParens());
607	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
608	        return own
609	            ? new Evaluator.ContainsWholeOwnText(searchText)
610	            : new Evaluator.ContainsWholeText(searchText);
611	    }
612	
613	    // pseudo selector :containsData(data)
614	    private Evaluator containsData() {
615	        String searchText = TokenQueue.unescape(consumeParens());
616	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
617	        return new Evaluator.ContainsData(searchText);
618	    }
619	
620	    // :matches(regex), matchesOwn(regex)
621	    private Evaluator matches(boolean own) {
622	        String query = own ? ":matchesOwn" : ":matches";
623	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
624	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
625	        Regex pattern = Regex.compile(regex);
626	
627	        if (inNodeContext)
628	            return new NodeEvaluator.MatchesValue(pattern);
629	
630	        return own
631	            ? new Evaluator.MatchesOwn(pattern)
632	            : new Evaluator.Matches(pattern);
633	    }
634	
635	    // :matches(regex), matchesOwn(regex)
636	    private Evaluator matchesWholeText(boolean own) {
637	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
638	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
639	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
640	
641	        Regex pattern = Regex.compile(regex);
642	        return own
643	            ? new Evaluator.MatchesWholeOwnText(pattern)
644	            : new Evaluator.MatchesWholeText(pattern);
645	    }
646	
647	    // :not(selector)
648	    private Evaluator not() {
649	        String subQuery = consumeParens();
650	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
651	
652	        return new StructuralEvaluator.Not(parse(subQuery));
653	    }
654	
655	    // pseudo selector :lang(en), :lang("en-US")
656	    private Evaluator lang() {
657	        String arg = consumeParens().trim(); // whitespace just inside the parens is ignored
658	        Validate.notEmpty(arg, ":lang() must have a language range");
659	
660	        final String range;
661	        final char first = arg.charAt(0);
662	        if (first == '\'' || first == '"') {
663	            // a quoted range must close at the very end of the argument, with nothing after it
664	            Validate.isTrue(arg.length() > 1 && arg.charAt(arg.length() - 1) == first,
665	                ":lang() has an unclosed quote or trailing content after the language range");
666	            range = arg.substring(1, arg.length() - 1);
667	        } else {
668	            range = arg;
669	        }
670	
671	        Validate.notEmpty(range, ":lang() must have a language range");
672	        for (int i = 0; i < range.length(); i++) {
673	            char c = range.charAt(i);
674	            Validate.isFalse(c == ',' || StringUtil.isWhitespace(c),
675	                ":lang() language range must not contain whitespace or commas");
676	        }
677	        return new Evaluator.Lang(range);
678	    }
679	
680	    @Override
681	    public String toString() {
682	        return query;
683	    }
684	
685	    @Override
686	    public void close() {
687	        tq.close();
688	    }
689	}
