import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Probe {
    static int fails = 0;
    static void check(String name, Runnable r) {
        try { r.run(); System.out.println("PASS " + name); }
        catch (Throwable t) { System.out.println("FAIL " + name + ": " + t); fails++; }
    }
    static void expectParseError(String name, String css) {
        try { Document d = Jsoup.parse("<div><p>x</p></div>"); d.select(css);
            System.out.println("FAIL " + name + ": no error for " + css); fails++; }
        catch (Selector.SelectorParseException e) { System.out.println("PASS " + name + " -> " + e.getMessage().replaceAll("\\s+"," ").substring(0,Math.min(80,e.getMessage().length()))); }
        catch (Throwable t) { System.out.println("FAIL " + name + ": wrong ex " + t); fails++; }
    }
    static void ids(String label, Elements els) {
        StringBuilder sb = new StringBuilder(label + " => [");
        for (Element e : els) sb.append(e.id()).append(",");
        sb.append("]");
        System.out.println(sb);
    }
    public static void main(String[] args) {
        // 1. basic relative scoping
        Document d = Jsoup.parse(
            "<div id=a><article id=art><h1 id=h1></h1><h2 id=h2></h2></article>" +
            "<article id=b><h2 id=h2b></h2></article></div>" +
            "<div id=other><h2 id=h2o></h2></div>");
        check("h1:has(+h2) direct sibling", () -> {
            Elements els = d.select("h1:has(+ h2)");
            if (els.size() != 1 || !els.first().id().equals("h1")) throw new AssertionError(els.eachAttr("id").toString());
        });
        check("article:has(h1 ~ h2) does NOT escape subtree", () -> {
            Elements els = d.select("article:has(h1 ~ h2)");
            // h1 and h2 are siblings inside art -> art matches per CSS? h1~h2: both inside art, yes matches
            ids("h1~h2", els);
        });
        check("div:has(article h2) descendant only", () -> {
            Elements els = d.select("div:has(article h2)");
            ids("div article h2", els); // a should match; what about html/body? select from doc root
        });
        // scope leak: h2 inside other branch should not be seen by article
        check("article:has(h1 + h2) only within scope", () -> {
            Elements els = d.select("article:has(h1 + h2)");
            ids("art h1+h2", els);
        });
        // nested :has inside :not
        Document d2 = Jsoup.parse("<div id=x><p><span>1</span></p></div><div id=y><p>2</p></div>");
        check("div:not(:has(span))", () -> {
            Elements els = d2.select("div:not(:has(span))");
            ids("not-has", els);
        });
        // comma branches, candidate once
        Document d3 = Jsoup.parse("<div id=x><span></span><p></p></div>");
        check("multi branch dedup", () -> {
            Elements els = d3.select("div:has(span, p)");
            if (els.size() != 1 || !els.first().id().equals("x")) throw new AssertionError(els.size());
        });
        // one failing branch shouldn't kill others
        expectParseError("unclosed :has", "div:has(span");
        expectParseError("empty :has", "div:has()");
        expectParseError("trailing combinator in :has", "div:has(>)");
        expectParseError("combinator no right", "div:has(span >)");
        expectParseError("empty comma branch", "div:has(span,,p)");
        expectParseError("empty first branch", "div:has(,p)");
        expectParseError("nested bad", "div:has(:not())");
        // wildcard inside
        check(":has(*)", () -> {
            Document dw = Jsoup.parse("<div id=a></div><div id=b>x</div>");
            Elements els = dw.select("div:has(*)");
            ids("has-star", els);
        });
        // repeated calls stable, doc unmodified
        check("idempotent & order", () -> {
            Document dd = Jsoup.parse("<div id=p1><div id=c><p id=pp></p></div></div><div id=p2><p></p></div>");
            String html = dd.html();
            Elements r1 = dd.select("div:has(p)");
            Elements r2 = dd.select("div:has(p)");
            ids("run1", r1); ids("run2", r2);
            if (!r1.eachAttr("id").equals(r2.eachAttr("id"))) throw new AssertionError("order differs");
            if (!dd.html().equals(html)) throw new AssertionError("doc modified");
        });
        // escaped class name
        check("escaped class in :has", () -> {
            Document de = Jsoup.parse("<div id=x><p class='a.b'></p></div>");
            Elements els = de.select("div:has(.a\\.b)");
            if (els.size() != 1) throw new AssertionError(els.size());
        });
        // empty doc
        check("empty doc", () -> {
            Document de = Jsoup.parse("");
            Elements els = de.select("div:has(p)");
            if (!els.isEmpty()) throw new AssertionError();
        });
        // table foster parenting / actual DOM
        check("table actual structure", () -> {
            Document dt = Jsoup.parse("<table id=t><p id=p><span id=s></span></p><tr id=tr><td id=td></td></tr></table>");
            Elements els = dt.select("p:has(span)");
            if (els.size() != 1) throw new AssertionError(els.size());
            // p is foster-parented; query td:has
            Elements tdHas = dt.select("td:has(*)");
            ids("td-has", tdHas);
        });
        // nested :has scope layer by layer
        check("nested :has scope", () -> {
            Document dn = Jsoup.parse(
                "<section id=s1><div id=d1><p id=p1><a id=a1></a></p></div></section>" +
                "<section id=s2><div id=d2><a id=a2></a></div></section>");
            Elements els = dn.select("section:has(div:has(p a))");
            ids("nested", els); // only s1
        });
        // child combinator direct only
        check("direct child in has", () -> {
            Document dc = Jsoup.parse("<div id=x><section id=sec><p id=pp></p></section></div><div id=y><p id=yp></p></div>");
            Elements els = dc.select("div:has(> p)");
            ids("direct", els); // y only
        });
        // :has with attribute quoted value containing quote
        check("attr quotes", () -> {
            Document da = Jsoup.parse("<div id=x><a title=\"he'llo\"></a></div>");
            Elements els = da.select("div:has(a[title=\"he'llo\"])");
            if (els.size() != 1) throw new AssertionError(els.size());
        });
        // sibling branches don't leak descendants of other branches
        check("~ sibling scoped to following siblings only", () -> {
            Document ds = Jsoup.parse(
                "<div id=wrap><h1 id=h></h1><div id=mid><h2 id=inside></h2></div></div>");
            // h:has(~ h2): h2 inside later sibling subtree DOES match in CSS (~ sees following siblings and their descendants)
            Elements els = ds.select("h1:has(~ h2)");
            ids("h1~h2-following", els); // h should match (h2 is descendant of following sibling)
            // wrap:has(+ div) should not match based on a div nested elsewhere
            Document ds2 = Jsoup.parse("<div id=outer><div id=wrap></div><section><div id=else></div></section></div>");
            Elements e2 = ds2.select("#wrap:has(+ div)");
            ids("wrap+div", e2); // none: immediate next sibling is section, not div
        });
        System.out.println(fails == 0 ? "ALL OK" : fails + " FAILURES");
    }
}
